import React, { createContext, useContext, useState, ReactNode, useEffect } from 'react';
import '../../../src/sass/_mpa_variables.scss';
import '../../../src/sass/_mpa_blueTheme.scss';
import '../../../src/sass/_mpa_greenTheme.scss';

type Theme = 'Blue' | 'Green';

interface ThemeContextType {
  theme: Theme;
  setTheme: (theme: Theme) => void;
}

const ThemeContext = createContext<ThemeContextType | undefined>(undefined);

export const ThemeProvider: React.FC<{ children: ReactNode; initialTheme?: Theme }> = ({ children, initialTheme = 'Blue' }) => {
  
  const [theme, setTheme] = useState<Theme>(initialTheme);

  useEffect(() => {
    document.documentElement.setAttribute('data-theme', theme);
  }, [theme]);


  const changeTheme = (theme: Theme) => {
    document.documentElement.setAttribute('data-theme', theme);
    setTheme(theme);
  };

  return (
    <ThemeContext.Provider value={{ theme, setTheme: changeTheme }}>
      {children}
    </ThemeContext.Provider>
  );
};

export const useTheme = () => {
  //console.log('useTheme');
  const context = useContext(ThemeContext);
  if (!context) {
    throw new Error('useTheme must be used within a ThemeProvider');
  }
  return context;
};
